const now = new Date();
const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const missionDateTime = new Date(`${d.mission_date}T${d.start_time || '09:00'}:00`);
  const diffMs = missionDateTime - now;
  const diffHours = diffMs / (1000 * 60 * 60);

  let action = null;

  // H-2 check: within 2h of start and reminder3 not sent
  if (diffHours <= 2 && diffHours > 0 && !d.reminder_3_sent_at) {
    action = 'REMINDER_3_H2';
  }
  // H-2 overdue (past start time) and still no confirmation
  else if (diffHours <= 0 && diffHours > -1 && !d.reminder_3_sent_at) {
    action = 'HIGH_RISK_NO_RESPONSE';
  }
  // J-1 at 16:00 window (between 15:45 and 16:30 the day before)
  else if (!d.reminder_2_sent_at && d.reminder_2_scheduled_at) {
    const r2 = new Date(d.reminder_2_scheduled_at);
    const r2Diff = (now - r2) / (1000 * 60);
    if (r2Diff >= 0 && r2Diff < 45) action = 'REMINDER_2_J1';
  }
  // J-2 at 10:00 window
  else if (!d.reminder_1_sent_at && d.reminder_1_scheduled_at) {
    const r1 = new Date(d.reminder_1_scheduled_at);
    const r1Diff = (now - r1) / (1000 * 60);
    if (r1Diff >= 0 && r1Diff < 45) action = 'REMINDER_1_J2';
  }

  if (action) {
    results.push({ json: { ...d, action, now: now.toISOString(), diffHours } });
  }
}

return results;

